from __future__ import annotations

import json
from datetime import datetime, timezone

import pytest

from gitseed.application import execute
from gitseed.artifact import EngineVersionMismatch, RunArtifact
from gitseed.collect.search import Candidate, CollectResult
from gitseed.grade.types import GradeResult
from gitseed.pipeline.run import FetchedFiles
from gitseed.ports import RepositoryMetadata, RunPorts, RunRequest
from gitseed.scoring import ScoreInputs
from gitseed.storage import SQLiteRunStore


AT = datetime(2026, 7, 27, 12, 0, tzinfo=timezone.utc)
CANDIDATE = Candidate("org/repo", "org", "https://github.com/org/repo", 4, "2026-07-27T00:00:00Z")


class Repository:
    def search(self, query: str, limit: int) -> CollectResult:
        return CollectResult(candidates=[CANDIDATE], pages_fetched=1)

    def metadata(self, candidate: Candidate, at: datetime) -> RepositoryMetadata:
        return RepositoryMetadata(ScoreInputs(True, True, True))


class Files:
    def read(self, candidate: Candidate) -> FetchedFiles:
        return FetchedFiles((("main.py", "def add(a, b):\n    return a + b\n"),))


class Model:
    def evaluate(self, digest: str) -> GradeResult:
        return GradeResult(8, 7, "small utility", "fixture", 0.0, "fixture-v1")

    def flags_malicious(self, digest: str) -> bool:
        return False


class Clock:
    def now(self) -> datetime:
        return AT


def artifact(source_mode: str) -> RunArtifact:
    return execute(
        RunRequest("small tools", 1),
        RunPorts(Repository(), Files(), Model(), Clock()),
        source_mode=source_mode,
    )


def changed_artifact(recorded: RunArtifact, change) -> RunArtifact:
    payload = json.loads(recorded.to_bytes())
    change(payload)
    return RunArtifact.from_bytes(json.dumps(payload).encode())


def test_store_replay_recomputes_a_full_source_record_without_replacing_it(tmp_path) -> None:
    expected = artifact("full-source")
    stored = changed_artifact(
        expected,
        lambda payload: payload["output"]["scores"][0]["score"].__setitem__("value", "999"),
    )

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        store.save("run-1", stored)
        before = store.load("run-1").to_bytes()

        replayed = store.replay("run-1")

        assert replayed.to_bytes() == expected.to_bytes()
        assert store.load("run-1").to_bytes() == before


@pytest.mark.parametrize("source_mode", ("metadata-only", "digest"))
def test_store_replay_rejects_non_full_source_records_without_changing_them(tmp_path, source_mode: str) -> None:
    recorded = artifact(source_mode)

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        store.save("run-1", recorded)
        before = store.load("run-1").to_bytes()

        with pytest.raises(ValueError, match=rf"cannot re-evaluate a {source_mode} artifact"):
            store.replay("run-1")

        assert store.load("run-1").to_bytes() == before


def test_store_replay_rejects_an_engine_mismatch_without_changing_the_record(tmp_path) -> None:
    recorded = changed_artifact(
        artifact("full-source"),
        lambda payload: payload["engines"].__setitem__("pipeline", "pipeline-v0"),
    )

    with SQLiteRunStore(tmp_path / "runs.db") as store:
        store.save("run-1", recorded)
        before = store.load("run-1").to_bytes()

        with pytest.raises(EngineVersionMismatch, match="pipeline engine changed"):
            store.replay("run-1")

        assert store.load("run-1").to_bytes() == before
